PLURALS = {'c_years_ago': [
    {'one': '%s year ago', 'other': '%s years ago'},
    {'one': 'hace %s año', 'other': 'hace %s años'},
    {'one': 'há %s ano', 'other': 'há %s anos'},
    {'one': 'il y a %s an', 'other': 'il y a %s ans'},
    {'zero': 'منذ %s سنة', 'one': 'منذ سنة', 'two': 'منذ سنتين', 'few': 'منذ %s سنوات', 'many': 'منذ %s سنة', 'other': 'منذ %s سنة'},
]}


def esc(t):
    t = escape(t).replace("'", "\\'").replace('"', '\\"')
    return ('\\' + t) if t.startswith('@') or t.startswith('?') else t


for i, lang in enumerate(LANGS):
    d = 'android/res/values' + ('' if lang == 'en' else '-' + lang)
    os.makedirs(d, exist_ok=True)
    out = ['<?xml version="1.0" encoding="utf-8"?>', '<!-- generated by tools/strings_res.py -->', '<resources>']
    for k, v in S.items():
        assert len(v) == len(LANGS), k
        fmt = '' if '%' in v[i] else ' formatted="false"' if False else ''
        out.append('    <string name="%s"%s>%s</string>' % (k, fmt, esc(v[i])))
    for k, v in PLURALS.items():
        out.append('    <plurals name="%s">' % k)
        for q, t in v[i].items():
            out.append('        <item quantity="%s">%s</item>' % (q, esc(t)))
        out.append('    </plurals>')
    out.append('</resources>')
    open(d + '/strings.xml', 'w', encoding='utf-8').write('\n'.join(out) + '\n')
print('strings written for', ', '.join(LANGS))
